-- 方便地读取 c# LuaParameters.cs 中的数据

---@class LuaParametersReader
local LuaParametersReader = {}


-- 需与 LuaParametersInspector.cs 中的 pairTypes 内容一致;
LuaParametersReader.Type = 
{
    String      = "String", 
    Bool        = "Bool", 
    Enum        = "Enum", 
    Int         = "Int", 
    Float       = "Float", 
    Vector2     = "Vector2", 
    Vector3     = "Vector3", 
    Vector4     = "Vector4", 
    Color       = "Color"
}


-- 需与 LuaParametersExpand.cs 中的 pairTypes 内容一致;
LuaParametersReader.ExpandType = 
{
    Curve       = "Curve", 
    Component   = "Component", 
    List        = "List"
}


-- =========================================== Static Functions ================================================ --


--- param enums_ 可选 table; 格式为: Type = { Cat=0, Human=1 }, 每个元素的 value 无约束, 只要 key 互不相同即可
LuaParametersReader.ReadEnum = function( p_, enums_ )

    assert( isTable(enums_) ) -- 用户必须提供 enum, 否则我们不知道返回啥

    local elements = string.split( p_.stringValue, ',' ) -- lua table array
    assert( table.count(elements) > p_.intValue, "enum idx 值异常" )

    local names = {} -- HashSet, 类型检查用
    --------
    local tgtElementLowName = nil -- 我们要找大的 enum 实例值, string, 比如 {Cat=0, Huamn=1} 中的 "cat" (主动转换为小写格式)
    for i=0, table.count(elements)-1 do 
        local e = elements[i+1]
        assert( type(e)=="string" and #e>0, "enum 元素不能为 空字符串" )

        e = string.lower(e) -- 允许用户大小写写错

        if i == p_.intValue then
            tgtElementLowName = e
        end

        if names[e] ~= 1 then 
            names[e] = 1
        end
    end
    assert( type(tgtElementLowName) == "string" ) 
    assert( table.count(enums_) == table.count(names), "inspector端 和 lua代码端 enum 存在差异" ) -- enum 中每个元素的 key 都不为空字符串,且要相互不同
    --------
    for k,v in pairs(enums_) do 
        if string.lower(k) == tgtElementLowName then 
            return v; -- 我们想要的
        end
    end
    ---
    assert( false, "没能找到目标 enum element" )
    return 0
end



LuaParametersReader.ReadComponent = function( p_ )
    assert( type(p_.componentType) == "string" )
    assert( #p_.componentType > 0 )
    assert( not isNull( p_.singleObj ) ) -- UnityEngine.Object
    local obj = p_.singleObj
    assert( not isNull(obj), "singleObj 为空" )

    local ret = nil -- Component
    local components = obj:GetComponents(typeof(Component)) -- Component[]
    assert( components.Length > 0 )
    for i=0, components.Length-1 do
        local com = components[i]
        if( com:GetType().FullName == p_.componentType ) then
            ret = com
            break
        end
    end
    assert( not isNull(ret) , "obj: " .. obj.name .. " 中没找到目标 component" )
    return ret
end




-- 将原来的 List<UnityEngine.Object> 转换为 lua table array: Component[]
LuaParametersReader.ReadList = function( p_ )

    assert( type(p_.componentType) == "string" )
    assert( #p_.componentType > 0 )
    assert( not isNull( p_.list ) ) -- List<Object>

    local ret = {} -- Component[]

    for j=0, p_.list.Count-1 do
        local obj = p_.list[j]
        assert( not isNull(obj), "发现绑定的 list 元素为空" )
        
        local isFind = false -- bool
        local components = obj:GetComponents(typeof(Component)) -- Component[]

        assert( components.Length > 0 )
        for i=0, components.Length-1 do
            local com = components[i]
            if( com:GetType().FullName == p_.componentType ) then
                table.insert( ret, com )
                isFind = true
                break
            end
        end
        assert( isFind == true, "obj: " .. obj.name .. " 中没找到目标 component" )
    end
    return ret
end


-- 只关心是否存在某个 key
---@return boolean
LuaParametersReader.IsFindKey = function( comp_, key_ )
    assert( not isNull(comp_) )
    assert( (type(key_) == "string") and (#key_ > 0) )

    assert( not isNull( comp_.keyValueList) )
    local len = comp_.keyValueList.Count
    assert( len > 0 )

    for i=0, len-1 do
        local p = comp_.keyValueList[i] -- List
        if (not isNull(p)) and (p.key == key_) then 
            return true
        end
    end
    return false
end



-- 一次读取一个 parameter:

--- return 数种类型之一: String, Int, Float, Vector2, Vector3, Vector4, Color, List
--- param comp_ LuaParameters / LuaParametersExpand
--- param key_  string 
--- param type_ LuaParameters.Type / LuaParameters.ExpandType  -- 用户来显示声明自己需要的参数的类型,(需与 inspector 面板中设置的类型一致)
--- param enums_ 可选 table; 格式为: Type = { Cat=0, Human=1 }, 每个元素的 value 无约束, 只要 key 互不相同即可
LuaParametersReader.Read = function( comp_, key_, type_, enums_ )
    assert( not isNull(comp_) )
    assert( (type(key_) == "string") and (#key_ > 0) )

    assert( not isNull( comp_.keyValueList) )
    local len = comp_.keyValueList.Count
    assert( len > 0 )

    local ret = nil
    for i=0, len-1 do
        local p = comp_.keyValueList[i] -- List
        if (not isNull(p)) and (p.key == key_) then 
            
            -- 可选的 类型检查
            assert( type(type_)=="string" )

            --if type(type_)=="String" then 
                assert( #type_>0 )
                assert( type_ == p.valueType, "参数类型异常: type_: " .. type_ .. ";  valueType: " .. p.valueType .. "; key: " .. p.key )
            --end

            if      p.valueType == LuaParametersReader.Type.String then 
                ret = p.stringValue

            elseif p.valueType ==  LuaParametersReader.Type.Bool  then
                ret = (p.intValue ~= 0)

            elseif p.valueType ==  LuaParametersReader.Type.Enum  then
                ret = LuaParametersReader.ReadEnum( p, enums_ ) -- Enum

            elseif p.valueType ==  LuaParametersReader.Type.Int  then
                ret = p.intValue

            elseif p.valueType == LuaParametersReader.Type.Float  then
                ret = p.vector4Value.x

            elseif p.valueType == LuaParametersReader.Type.Vector2  then
                ret = Vector2( p.vector4Value.x, p.vector4Value.y )

            elseif p.valueType == LuaParametersReader.Type.Vector3  then
                ret = Vector3( p.vector4Value.x, p.vector4Value.y, p.vector4Value.z )

            elseif p.valueType == LuaParametersReader.Type.Vector4  then
                ret = p.vector4Value

            elseif p.valueType == LuaParametersReader.Type.Color  then
                ret = p:GetColorValue()


            -- ==== 下面是 LuaParametersExpand 部分的参数:

            elseif p.valueType == LuaParametersReader.ExpandType.Curve  then
                assert( not isNull(p.curve) )
                ret = p.curve

            elseif p.valueType == LuaParametersReader.ExpandType.Component  then
                ret = LuaParametersReader.ReadComponent( p ) -- Component
                
            elseif p.valueType == LuaParametersReader.ExpandType.List  then
                ret = LuaParametersReader.ReadList( p ) -- table array

            else 
                assert( "没找到目标类型, 请检查代码" )
            end
            break
        end
    end
    assert( not isNull(ret) )
    return ret
end






return LuaParametersReader

